import gsap from 'gsap';
import { uv, mix, vec3 } from 'three/tsl';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE, fontAtlas, emit } = ctx;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const root = new Group();
  if (config.scenePosition) {
    root.position.copy(config.scenePosition);
  }

  // Contact shadow plane
  const shadowGeo = new PlaneGeometry(3.6 * 1.15, 0.5 * 1.15);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.z = -0.001;
  shadow.position.y = -0.06;
  shadow.renderOrder = 0;
  root.add(shadow);

  // Rail with brushed metal PBR
  const railGeo = new PlaneGeometry(3.6, 0.5);
  const railMat = new MeshStandardNodeMaterial();

  // Vertical gradient: #1b1b23 at bottom (y=0) to #101015 at top (y=1)
  const uvNode = uv();
  const color1 = vec3(new Color(0x1b1b23));
  const color2 = vec3(new Color(0x101015));
  railMat.colorNode = mix(color1, color2, uvNode.y);

  railMat.metalness = 0.5;
  railMat.roughness = 0.55;
  railMat.clearcoat = 0.2;
  railMat.anisotropy = 0.6;

  const rail = new Mesh(railGeo, railMat);
  rail.position.z = 0.15;
  rail.renderOrder = 1;
  root.add(rail);

  // Navigation entries
  const entries = [
    { label: 'HOME', isActive: true, navTo: 'hub-home' },
    { label: 'FEATURES', isActive: false, navTo: 'hub-features' },
    { label: 'COLLECTION', isActive: false, navTo: 'hub-collection' },
    { label: 'PRICING', isActive: false, navTo: 'hub-pricing' },
    { label: 'JOURNAL', isActive: false, navTo: 'hub-journal' },
  ];

  const spacing = 0.68;
  const totalWidth = spacing * (entries.length - 1);
  const startX = -totalWidth / 2;

  const entryContainer = new Group();
  entryContainer.position.z = 0.15 + 0.01;
  root.add(entryContainer);

  const entryData = [];

  // Create text entries
  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i];
    const x = startX + i * spacing;
    const color = entry.isActive ? '#e8ecf2' : '#a6adba';

    const textGroup = fontAtlas.createText(entry.label, {
      fontSize: 13,
      color,
      align: 'center',
      letterSpacingPx: 1.04,
    });

    textGroup.position.set(x, 0, 0.02);
    entryContainer.add(textGroup);

    let material = null;
    textGroup.traverse((child) => {
      if (child.isMesh && child.material && !material) {
        material = child.material;
      }
    });

    entryData.push({
      index: i,
      label: entry.label,
      textGroup,
      material,
      color,
    });
  }

  // Underline indicator bar
  const underlineGeo = new PlaneGeometry(0.28, 0.025);
  const underlineMat = new MeshStandardNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8,
    metalness: 0,
    roughness: 1,
  });
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.set(startX, -0.06, 0.01);
  underline.renderOrder = 2;
  entryContainer.add(underline);

  // Mount animation: rise-in
  gsap.from(root, {
    y: 0.4,
    duration: 0.7,
    ease: 'power3.out',
  });

  // Navigation handler
  const updateActiveEntry = (newIndex) => {
    const oldActive = entries.findIndex(e => e.isActive);
    if (oldActive === newIndex) return;

    entries[oldActive].isActive = false;
    entries[newIndex].isActive = true;

    // Animate underline to new position
    const newX = startX + newIndex * spacing;
    gsap.to(underline.position, {
      x: newX,
      duration: 0.26,
      ease: 'power3.out',
    });

    // Update text colors
    entryData.forEach((data, i) => {
      const shouldBeActive = i === newIndex;
      const newColor = shouldBeActive ? '#e8ecf2' : '#a6adba';

      if (data.color !== newColor) {
        data.color = newColor;

        // Recreate text with new color
        entryContainer.remove(data.textGroup);

        const newTextGroup = fontAtlas.createText(data.label, {
          fontSize: 13,
          color: newColor,
          align: 'center',
          letterSpacingPx: 1.04,
        });

        newTextGroup.position.copy(data.textGroup.position);
        entryContainer.add(newTextGroup);

        let material = null;
        newTextGroup.traverse((child) => {
          if (child.isMesh && child.material && !material) {
            material = child.material;
          }
        });

        data.textGroup = newTextGroup;
        data.material = material;
      }
    });
  };

  // Export handlers
  root.userData.handlers = {
    navigate: (index) => {
      emit('navigate', { to: entries[index].navTo });
      updateActiveEntry(index);
    },
    press: (index) => {
      const data = entryData[index];
      gsap.to(data.textGroup.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
      gsap.to(data.textGroup.position, {
        z: -0.01,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    release: (index) => {
      const data = entryData[index];
      gsap.to(data.textGroup.scale, {
        x: 1,
        y: 1,
        duration: 0.12,
        ease: 'back.out',
      });
      gsap.to(data.textGroup.position, {
        z: 0.02,
        duration: 0.12,
        ease: 'back.out',
      });
    },
  };

  root.userData.cleanup = () => {
    gsap.killTweensOf(root);
    gsap.killTweensOf(underline.position);
    entryData.forEach((data) => {
      gsap.killTweensOf(data.textGroup);
      gsap.killTweensOf(data.textGroup.scale);
      gsap.killTweensOf(data.textGroup.position);
    });

    railGeo.dispose();
    railMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  return root;
}
